function(container, apiUrl, tables) {
  // KPI計算と表示
  function updateKPIs(records) {
    const totalOrders = records.length;
    const totalAmount = records.reduce((sum, r) => sum + (parseFloat(r.amount) || 0), 0);
    const pendingOrders = records.filter(r => r.status === '処理中' || r.status === '承認待ち').length;
    const completedOrders = records.filter(r => r.status === '完了').length;
    const completionRate = totalOrders > 0 ? Math.round((completedOrders / totalOrders) * 100) : 0;

    container.querySelector('[data-testid="kpi-total-orders"]').textContent = totalOrders.toLocaleString();
    container.querySelector('[data-testid="kpi-total-amount"]').textContent = `¥${totalAmount.toLocaleString()}`;
    container.querySelector('[data-testid="kpi-pending-orders"]').textContent = pendingOrders.toLocaleString();
    container.querySelector('[data-testid="kpi-completion-rate"]').textContent = `${completionRate}%`;

    // 緊急案件数更新
    const urgentCount = records.filter(r => r.priority === '緊急' || r.status === '承認待ち').length;
    container.querySelector('#urgent-count').textContent = `${urgentCount}件`;
  }

  // 月別推移チャート
  function initMonthlyChart(records) {
    const ctx = container.querySelector('#monthly-chart').getContext('2d');

    // 月別集計
    const monthlyData = {};
    records.forEach(record => {
      if (record.created_date) {
        const month = record.created_date.slice(0, 7); // YYYY-MM
        monthlyData[month] = (monthlyData[month] || 0) + 1;
      }
    });

    const sortedMonths = Object.keys(monthlyData).sort().slice(-6); // 直近6ヶ月
    const counts = sortedMonths.map(month => monthlyData[month] || 0);

    new Chart(ctx, {
      type: 'line',
      data: {
        labels: sortedMonths.map(m => m.slice(5)), // MM表示
        datasets: [{
          label: '発注件数',
          data: counts,
          borderColor: '#22c55e',
          backgroundColor: 'rgba(34, 197, 94, 0.1)',
          borderWidth: 2,
          fill: true,
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            display: false
          }
        },
        scales: {
          y: {
            beginAtZero: true,
            grid: {
              color: 'rgba(255,255,255,0.1)'
            },
            ticks: {
              color: '#9fb0d1'
            }
          },
          x: {
            grid: {
              color: 'rgba(255,255,255,0.1)'
            },
            ticks: {
              color: '#9fb0d1'
            }
          }
        }
      }
    });
  }

  // ステータス別分布チャート
  function initStatusChart(records) {
    const ctx = container.querySelector('#status-chart').getContext('2d');

    // ステータス別集計
    const statusData = {};
    records.forEach(record => {
      const status = record.status || '未設定';
      statusData[status] = (statusData[status] || 0) + 1;
    });

    const labels = Object.keys(statusData);
    const data = Object.values(statusData);
    const colors = ['#22c55e', '#3b82f6', '#f59e0b', '#ef4444', '#8b5cf6'];

    new Chart(ctx, {
      type: 'doughnut',
      data: {
        labels: labels,
        datasets: [{
          data: data,
          backgroundColor: colors.slice(0, labels.length),
          borderWidth: 0
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            position: 'bottom',
            labels: {
              color: '#9fb0d1',
              font: {
                size: 12
              },
              padding: 15
            }
          }
        }
      }
    });
  }

  // 初期データ読み込み
  async function loadDashboardData() {
    try {
      const records = await window.aivicApi.list(0);
      if (records) {
        updateKPIs(records);
        initMonthlyChart(records);
        initStatusChart(records);
      } else {
        // APIが利用できない場合は初期データを使用
        const initialRecords = tables[0]?.records || [];
        updateKPIs(initialRecords);
        initMonthlyChart(initialRecords);
        initStatusChart(initialRecords);
      }
    } catch (error) {
      console.error('Dashboard data loading failed:', error);
      // エラー時も初期データで表示
      const initialRecords = tables[0]?.records || [];
      updateKPIs(initialRecords);
      initMonthlyChart(initialRecords);
      initStatusChart(initialRecords);
    }
  }

  // 更新ボタンのイベントリスナー
  container.querySelector('[data-testid="refresh-btn"]').addEventListener('click', () => {
    loadDashboardData();
  });

  // 初期化実行
  loadDashboardData();
}

function(container, apiUrl, tables) {
  let currentData = tables[0]?.records || [];
  let sortField = '';
  let sortDirection = 'asc';

  // ステータス別の色分け
  function getStatusBadge(status) {
    const statusColors = {
      '要件定義': 'background: #3b82f6; color: #fff;',
      '設計中': 'background: #8b5cf6; color: #fff;',
      '開発中': 'background: #f59e0b; color: #fff;',
      'テスト中': 'background: #ef4444; color: #fff;',
      'リリース済': 'background: #10b981; color: #fff;',
      '保守運用': 'background: #6b7280; color: #fff;'
    };
    const style = statusColors[status] || 'background: #6b7280; color: #fff;';
    return `<span class="px-2 py-1 text-xs rounded-full" style="${style}">${status || '未設定'}</span>`;
  }

  // 優先度別の色分け
  function getPriorityBadge(priority) {
    const priorityColors = {
      '高': 'background: #ef4444; color: #fff;',
      '中': 'background: #f59e0b; color: #fff;',
      '低': 'background: #10b981; color: #fff;'
    };
    const style = priorityColors[priority] || 'background: #6b7280; color: #fff;';
    return `<span class="px-2 py-1 text-xs rounded-full" style="${style}">${priority || '中'}</span>`;
  }

  // 進捗バーの生成
  function getProgressBar(progress) {
    const percent = Math.min(100, Math.max(0, progress || 0));
    const color = percent >= 80 ? '#10b981' : percent >= 50 ? '#f59e0b' : '#ef4444';
    return `
      <div class="w-full bg-gray-200 rounded-full h-2" style="background: rgba(255,255,255,0.1);">
        <div class="h-2 rounded-full" style="width: ${percent}%; background: ${color};"></div>
      </div>
      <span class="text-xs ml-2" style="color: var(--text-muted);">${percent}%</span>
    `;
  }

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#projects-tbody');
    tbody.innerHTML = rows.map(row => `
      <tr class="hover:bg-opacity-50 cursor-pointer" data-id="${row.id || ''}" style="border-bottom: 1px solid rgba(255,255,255,0.08);">
        <td class="py-3 px-3">
          <div class="font-medium" style="color: var(--text);">${row.projectName || '未設定'}</div>
          <div class="text-xs" style="color: var(--text-muted);">${row.description || ''}</div>
        </td>
        <td class="py-3 px-3" style="color: var(--text);">${row.clientName || '未設定'}</td>
        <td class="py-3 px-3">${getStatusBadge(row.status)}</td>
        <td class="py-3 px-3">${getPriorityBadge(row.priority)}</td>
        <td class="py-3 px-3" style="color: var(--text);">¥${(row.budget || 0).toLocaleString()}</td>
        <td class="py-3 px-3" style="color: var(--text);">${row.startDate || '--'}</td>
        <td class="py-3 px-3">
          <div class="flex items-center">
            ${getProgressBar(row.progress)}
          </div>
        </td>
        <td class="py-3 px-3">
          <div class="flex gap-1">
            <button class="action-btn secondary text-xs px-2 py-1 edit-btn" data-id="${row.id || ''}">編集</button>
            <button class="action-btn secondary text-xs px-2 py-1 delete-btn" data-id="${row.id || ''}">削除</button>
          </div>
        </td>
      </tr>
    `).join('');

    // 結果件数の更新
    container.querySelector('#result-count').textContent = `${rows.length}件の案件を表示中`;
    container.querySelector('#last-updated').textContent = new Date().toLocaleString();

    updateKPIs(rows);
  }

  // KPI更新
  function updateKPIs(rows) {
    const total = rows.length;
    const active = rows.filter(r => ['要件定義', '設計中', '開発中', 'テスト中'].includes(r.status)).length;
    const totalBudget = rows.reduce((sum, r) => sum + (r.budget || 0), 0);
    const completed = rows.filter(r => r.status === 'リリース済').length;
    const completionRate = total > 0 ? Math.round((completed / total) * 100) : 0;

    container.querySelector('#kpi-total').textContent = total;
    container.querySelector('#kpi-active').textContent = active;
    container.querySelector('#kpi-budget').textContent = `¥${totalBudget.toLocaleString()}`;
    container.querySelector('#kpi-completion').textContent = `${completionRate}%`;
  }

  // ソート機能
  function sortData(field) {
    if (sortField === field) {
      sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
    } else {
      sortField = field;
      sortDirection = 'asc';
    }

    currentData.sort((a, b) => {
      let aVal = a[field] || '';
      let bVal = b[field] || '';

      if (field === 'budget') {
        aVal = parseFloat(aVal) || 0;
        bVal = parseFloat(bVal) || 0;
      } else if (field === 'startDate') {
        aVal = new Date(aVal || '1970-01-01');
        bVal = new Date(bVal || '1970-01-01');
      }

      if (aVal < bVal) return sortDirection === 'asc' ? -1 : 1;
      if (aVal > bVal) return sortDirection === 'asc' ? 1 : -1;
      return 0;
    });

    renderRows(currentData);
  }

  // 初期データの描画
  renderRows(currentData);

  // 最新データの取得
  window.aivicApi.list(0).then(rows => {
    if (rows) {
      currentData = rows;
      renderRows(currentData);
    }
  });

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', () => {
    const keyword = container.querySelector('#search-keyword').value.toLowerCase();
    const statusFilter = container.querySelector('#filter-status').value;
    const priorityFilter = container.querySelector('#filter-priority').value;

    window.aivicApi.list(0).then(rows => {
      if (rows) {
        let filtered = rows.filter(row => {
          const matchKeyword = !keyword || 
            (row.projectName || '').toLowerCase().includes(keyword) ||
            (row.clientName || '').toLowerCase().includes(keyword) ||
            (row.description || '').toLowerCase().includes(keyword);

          const matchStatus = !statusFilter || row.status === statusFilter;
          const matchPriority = !priorityFilter || row.priority === priorityFilter;

          return matchKeyword && matchStatus && matchPriority;
        });

        currentData = filtered;
        renderRows(filtered);
      }
    });
  });

  // ソートイベント
  container.addEventListener('click', (e) => {
    const sortBtn = e.target.closest('[data-sort]');
    if (sortBtn) {
      sortData(sortBtn.dataset.sort);
    }
  });

  // 行クリックで詳細画面へ
  container.addEventListener('click', (e) => {
    const row = e.target.closest('tr[data-id]');
    if (row && !e.target.closest('button')) {
      window.showScreen('scr-3');
    }
  });

  // 編集・削除ボタン
  container.addEventListener('click', async (e) => {
    const editBtn = e.target.closest('.edit-btn');
    const deleteBtn = e.target.closest('.delete-btn');

    if (editBtn) {
      window.showScreen('scr-3');
    }

    if (deleteBtn) {
      if (!confirm('この案件を削除しますか？')) return;

      const success = await window.aivicApi.delete(0, deleteBtn.dataset.id);
      if (success) {
        const updatedRows = await window.aivicApi.list(0);
        if (updatedRows) {
          currentData = updatedRows;
          renderRows(updatedRows);
        }
      }
    }
  });

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const headers = ['案件名', '顧客名', 'ステータス', '優先度', '予算', '開始日', '進捗率', '説明'];
    const csvContent = [
      headers.join(','),
      ...rows.map(row => [
        `"${(row.projectName || '').replace(/"/g, '""')}"`,
        `"${(row.clientName || '').replace(/"/g, '""')}"`,
        `"${(row.status || '').replace(/"/g, '""')}"`,
        `"${(row.priority || '').replace(/"/g, '""')}"`,
        row.budget || 0,
        `"${(row.startDate || '').replace(/"/g, '""')}"`,
        row.progress || 0,
        `"${(row.description || '').replace(/"/g, '""')}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `web発注プラットフォーム案件一覧_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });
}

function(container, apiUrl, tables) {
  // 現在編集中のプロジェクトID（URLパラメータから取得想定）
  let currentProjectId = null;

  // 初期データの設定
  function initializeForm() {
    if (tables && tables[0] && tables[0].records && tables[0].records.length > 0) {
      const project = tables[0].records[0];
      currentProjectId = project.id;

      // フォームに既存データを設定
      const projectName = container.querySelector('#project-name');
      const projectStatus = container.querySelector('#project-status');
      const startDate = container.querySelector('#start-date');
      const endDate = container.querySelector('#end-date');
      const budget = container.querySelector('#budget');
      const priority = container.querySelector('#priority');
      const description = container.querySelector('#description');
      const frontendTech = container.querySelector('#frontend-tech');
      const backendTech = container.querySelector('#backend-tech');
      const database = container.querySelector('#database');
      const cloudPlatform = container.querySelector('#cloud-platform');

      if (project.name) projectName.value = project.name;
      if (project.status) projectStatus.value = project.status;
      if (project.startDate) startDate.value = project.startDate;
      if (project.endDate) endDate.value = project.endDate;
      if (project.budget) budget.value = project.budget;
      if (project.priority) priority.value = project.priority;
      if (project.description) description.value = project.description;
      if (project.frontendTech) frontendTech.value = project.frontendTech;
      if (project.backendTech) backendTech.value = project.backendTech;
      if (project.database) database.value = project.database;
      if (project.cloudPlatform) cloudPlatform.value = project.cloudPlatform;
    }
  }

  // 保存ボタンのイベントリスナー
  container.querySelector('#save-button').addEventListener('click', async () => {
    const formData = {
      name: container.querySelector('#project-name').value,
      status: container.querySelector('#project-status').value,
      startDate: container.querySelector('#start-date').value,
      endDate: container.querySelector('#end-date').value,
      budget: parseInt(container.querySelector('#budget').value) || 0,
      priority: container.querySelector('#priority').value,
      description: container.querySelector('#description').value,
      frontendTech: container.querySelector('#frontend-tech').value,
      backendTech: container.querySelector('#backend-tech').value,
      database: container.querySelector('#database').value,
      cloudPlatform: container.querySelector('#cloud-platform').value,
      updatedAt: new Date().toISOString()
    };

    try {
      let result;
      if (currentProjectId) {
        // 更新
        result = await window.aivicApi.update(0, currentProjectId, formData);
      } else {
        // 新規作成
        result = await window.aivicApi.save(0, formData);
      }

      if (result) {
        alert('保存しました');
        window.showScreen('scr-2'); // 一覧画面に戻る
      } else {
        alert('保存に失敗しました');
      }
    } catch (error) {
      console.error('保存エラー:', error);
      alert('保存中にエラーが発生しました');
    }
  });

  // キャンセルボタンのイベントリスナー
  container.querySelector('#cancel-button').addEventListener('click', () => {
    if (confirm('変更を破棄して戻りますか？')) {
      window.showScreen('scr-2');
    }
  });

  // すべてのタスクを表示ボタン
  container.querySelector('[data-testid="view-all-tasks"]').addEventListener('click', () => {
    // タスク管理画面への遷移（仮想的な画面ID）
    alert('タスク管理画面への遷移機能は今後実装予定です');
  });

  // 進捗データの更新（模擬データ）
  function updateProgressData() {
    // 実際の実装では API からタスクデータを取得して計算
    const progressPercentage = container.querySelector('[data-testid="progress-percentage"]');
    const completedTasks = container.querySelector('[data-testid="completed-tasks"]');
    const remainingTasks = container.querySelector('[data-testid="remaining-tasks"]');

    // 模擬的な進捗計算
    const total = 34;
    const completed = 12;
    const remaining = total - completed;
    const percentage = Math.round((completed / total) * 100);

    progressPercentage.textContent = `${percentage}%`;
    completedTasks.textContent = completed.toString();
    remainingTasks.textContent = remaining.toString();
  }

  // 初期化実行
  initializeForm();
  updateProgressData();

  // 定期的な進捗データ更新（実際の実装では WebSocket や定期的な API 呼び出しを使用）
  setInterval(updateProgressData, 30000); // 30秒ごと
}
